import type { CSSProperties } from 'react'

import { imageManifest } from '../image-manifest'

/**
 * One optimised image from public/images: the responsive WebP set generated by
 * scripts/optimize-images.mjs. `sizes` tells the browser how wide the image is
 * drawn so it picks the right variant; width/height come from the file itself,
 * so the box is reserved before the image arrives and nothing shifts.
 *
 * Loading is lazy unless the image is above the fold (`eager`), and only the
 * one hero image on the homepage asks for `priority` (fetchpriority="high").
 */
export function Img({
  name,
  sizes,
  alt = '',
  className,
  style,
  eager,
  priority,
}: {
  /** File stem in public/images, e.g. "zammita" or "r-pasta". */
  name: string
  /** Layout width hint, e.g. "(min-width: 1024px) 32vw, 78vw". */
  sizes: string
  alt?: string
  className?: string
  style?: CSSProperties
  eager?: boolean
  priority?: boolean
}) {
  const meta = imageManifest[name]
  if (!meta) {
    // A name that is not in the manifest means the image was never optimised;
    // fall back to the un-suffixed file so the page still renders.
    if (import.meta.env.DEV) console.warn(`[Img] "${name}" is not in image-manifest.ts — run \`bun run images:optimize\``)
    return <img src={`/images/${name}.webp`} alt={alt} className={className} style={style} loading={eager ? 'eager' : 'lazy'} />
  }
  const widest = meta.widths[meta.widths.length - 1]
  return (
    <img
      src={`/images/${name}-${widest}.webp`}
      srcSet={meta.widths.map((w) => `/images/${name}-${w}.webp ${w}w`).join(', ')}
      sizes={sizes}
      width={meta.w}
      height={meta.h}
      alt={alt}
      loading={eager ? 'eager' : 'lazy'}
      decoding={priority ? 'sync' : 'async'}
      fetchPriority={priority ? 'high' : 'auto'}
      draggable={false}
      className={className}
      style={style}
    />
  )
}
